-- Maison Academy · new cards: 0011_service_steps (21 cards, unit "Service steps (11-step sequence)")
-- Generated by scripts/make_new_cards_sql.py from content/drafts/service-steps-cards.json. All arrive in review.
insert into public.units (id, track_id, name, sort) values ('service-steps', 'service', 'Service steps (11-step sequence)', 6)
on conflict (id) do nothing;

insert into public.cards (id, track_id, unit_id, level, roles, type, prompt, options, answer, explanation,
  why_it_matters, is_allergen, source_ref, review_note, status, updated_by)
values
  ('svc-service-steps-0001', 'service', 'service-steps', 1, array['server']::text[], 'order', 'Put the first six steps of the sequence of service in order.', '["Serving food", "Welcome", "Serving drinks", "Taking the drink order", "Taking the food order", "Checking on guest satisfaction"]'::jsonb, '["Welcome", "Taking the drink order", "Serving drinks", "Taking the food order", "Serving food", "Checking on guest satisfaction"]'::jsonb, 'Welcome, drink order, serve drinks, food order, serve food, then check the guests are enjoying their meal.', 'The same order every time means nothing is missed, however busy it gets.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), steps 1 to 6', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0002', 'service', 'service-steps', 1, array['server']::text[], 'order', 'Put the last five steps of the sequence of service in order.', '["Presenting the check", "Departing the guest", "Clearing plates", "Calling the main course", "Presenting the dessert menu"]'::jsonb, '["Calling the main course", "Clearing plates", "Presenting the dessert menu", "Presenting the check", "Departing the guest"]'::jsonb, 'Call the mains, clear, present the dessert menu, present the check, then see the guests off.', 'The end of the meal is what guests remember most, so it needs the same care as the start.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), steps 7 to 11', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0003', 'service', 'service-steps', 1, array['server','host']::text[], 'scenario', 'You reach a table and the guests are deep in conversation. What do you do?', '["Come back once they''ve stopped talking", "Start your welcome so they know you''re there", "Wait for them to call you over", "Wait a few seconds to catch their eye"]'::jsonb, '["Wait a few seconds to catch their eye"]'::jsonb, 'If the guests are talking, wait a few seconds to attract their attention. Never wait for a guest to approach you first.', 'Guests feel noticed without being interrupted.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 1', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0004', 'service', 'service-steps', 1, array['server','host']::text[], 'mcq', 'As you approach a table to introduce yourself, who do you make eye contact with?', '["The host of the table", "Whoever looks ready to order", "The oldest guest at the table", "The guest facing you"]'::jsonb, '["The host of the table"]'::jsonb, 'Make eye contact with the host as you approach the table, then introduce yourself as soon as possible.', 'The host is the person looking after the table''s guests, so they should feel looked after first.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 1', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0005', 'service', 'service-steps', 1, array['server','bar']::text[], 'multi', 'Entering a drinks order into Micros, what do you double-check? Pick all that apply.', '["Any special requests", "The guests'' names", "The price of each drink", "The number of guests", "The table number"]'::jsonb, '["The table number", "The number of guests", "Any special requests"]'::jsonb, 'Double-check the table number, the number of guests, and that the order went in correctly with every special request.', 'A mistyped table number sends the drinks to another table.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 2', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0006', 'service', 'service-steps', 1, array['server','runner','bar']::text[], 'mcq', 'How do you pick up a glass to serve it?', '["By the base or the stem", "With a napkin around the bowl", "By the body, away from the rim", "By the rim, so it stays steady"]'::jsonb, '["By the base or the stem"]'::jsonb, 'Pick up the glass by the base or stem, never the rim, with clean, dry hands and no fingerprints or lipstick marks on the glass.', 'Guests drink from the rim, so it must stay untouched.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 3', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0007', 'service', 'service-steps', 1, array['server','runner','bar']::text[], 'mcq', 'You arrive with a tray of drinks for a table. Who do you serve first?', '["Whoever is nearest to you", "The host of the table", "Ladies and older gentlemen", "The guest who ordered first"]'::jsonb, '["Ladies and older gentlemen"]'::jsonb, 'Serve ladies and older gentlemen first, announcing each drink as you serve it.', 'A consistent, courteous order is part of formal service.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 3', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0008', 'service', 'service-steps', 1, array['server','runner','bar']::text[], 'mcq', 'From which side of the guest do you serve drinks and food?', '["Drinks from the right, food from the left", "The guest''s left", "Food from the right, drinks from the left", "The guest''s right"]'::jsonb, '["The guest''s right"]'::jsonb, 'Announce and serve drinks from the right, and approach the guest from the right to serve food.', 'Serving from one side every time means you never reach across a guest.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), steps 3 and 5', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0009', 'service', 'service-steps', 1, array['server','runner','bar']::text[], 'mcq', 'You''ve served everyone their drinks. What now?', '["Ask \"Is everything OK with your drinks?\"", "Ask if they''re ready to order food", "Step back and say \"Enjoy your drinks!\"", "Leave quietly so you don''t interrupt"]'::jsonb, '["Step back and say \"Enjoy your drinks!\""]'::jsonb, 'When everyone has been served, take a step back and say "Enjoy your drinks!"', 'A small, warm close makes the moment feel finished.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 3', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0010', 'service', 'service-steps', 1, array['server']::text[], 'mcq', 'What must you do before leaving the table with a food order?', '["Repeat the order back to each guest", "Check it on the POS while at the table", "Read the whole order back to the host", "Confirm the total with the host"]'::jsonb, '["Repeat the order back to each guest"]'::jsonb, 'Repeat the order back to each guest with eye contact. You must be 100% sure the order is understood and recorded correctly before you leave.', 'Repeating it back catches mistakes before the kitchen starts cooking.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 4', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0011', 'service', 'service-steps', 1, array['server']::text[], 'multi', 'Taking the food order, what must you find out from your guests? Pick all that apply.', '["Any dietary requirements", "Their seating preference", "Any allergies", "How they''ll pay", "Their names"]'::jsonb, '["Any allergies", "Any dietary requirements"]'::jsonb, 'Collect all the information you need, such as allergies and dietary requirements, and explain dishes so guests know what they''re ordering.', 'An allergy missed at the order can''t be fixed once the dish is cooked.', true, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 4', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026). Allergen card: needs the kitchen check.', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0012', 'service', 'service-steps', 1, array['server','runner']::text[], 'mcq', 'What''s the most plates you should carry at one time?', '["2", "As many as you can carry safely", "4", "3"]'::jsonb, '["3"]'::jsonb, 'Never carry more than 3 plates at a time, and hold them straight so no sauce spills.', 'Fewer plates means no spills and no dropped food at the table.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 5', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0013', 'service', 'service-steps', 1, array['server','runner']::text[], 'mcq', 'You''re about to serve a plate but the guest hasn''t seen you. What do you say?', '["Nothing; wait until they notice you", "\"Here''s your food\"", "\"May I?\"", "\"Excuse me!\""]'::jsonb, '["\"May I?\""]'::jsonb, 'Approach from the right, and if the guest doesn''t see you, say "May I?"', 'It avoids startling the guest or knocking into them.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 5', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0014', 'service', 'service-steps', 1, array['server','runner']::text[], 'mcq', 'Serving sauces or condiments, what do you tell the guest?', '["Name, price and whether it''s spicy", "Just the name", "Ingredients, but only if asked", "Name, ingredients and how spicy"]'::jsonb, '["Name, ingredients and how spicy"]'::jsonb, 'Serve the sauces or condiments and explain what they are: name, ingredients and spiciness.', 'Guests can''t enjoy a sauce they''re unsure about, especially if it''s hot.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 5', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0015', 'service', 'service-steps', 1, array['server','runner']::text[], 'mcq', 'Before taking plates to a table, what do you check them against?', '["The captain order", "The table plan", "The menu descriptions", "The guests'' bill"]'::jsonb, '["The captain order"]'::jsonb, 'Double-check the food against the captain order, make sure plates are clean of drips and fingerprints, and that you have the right condiments.', 'Catching a missing or mixed-up dish at the pass saves the guest a wait.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 5', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0016', 'service', 'service-steps', 1, array['server']::text[], 'mcq', 'How often must you check on each table''s satisfaction during a meal?', '["After every course, every time", "Only when you clear plates", "At least once", "Only if they call you over"]'::jsonb, '["At least once"]'::jsonb, 'Visit each table at least once during the meal to check the guests are enjoying their food and drinks.', 'Guests who aren''t happy often won''t say so unless you ask.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 6', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0017', 'service', 'service-steps', 1, array['server','host','runner','bar','barista']::text[], 'mcq', 'A guest complains about a dish. How should you see it?', '["As something for the manager to handle", "As a one-off to apologise for and move on", "As feedback to pass to the kitchen later", "As a second chance to win them back"]'::jsonb, '["As a second chance to win them back"]'::jsonb, 'A guest who complains gives you a second chance, unlike guests who say nothing and never return, so do whatever it takes to recover them.', 'A complaint handled well can win a guest for life.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 6', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0018', 'service', 'service-steps', 1, array['server']::text[], 'mcq', 'How do you know when to call the main course?', '["Watch how fast the table is eating", "Once all the starter plates are cleared", "As soon as the starters are served", "When the guests ask for their mains"]'::jsonb, '["Watch how fast the table is eating"]'::jsonb, 'Monitor the meal, estimate how fast the guests are eating, then go to the service station and send the mains away.', 'Good timing means mains arrive just as guests are ready, not too soon or too late.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 7', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0019', 'service', 'service-steps', 1, array['server','runner']::text[], 'mcq', 'Clearing a plate, how do you hold the cutlery?', '["Knife handle to your thumb, thumb on it, fork slid under the knife", "Fork handle to your thumb, thumb on it, knife slid under the fork", "Fork handle to your thumb, knife laid on top of the fork", "Fork and knife side by side, held under your fingers"]'::jsonb, '["Fork handle to your thumb, thumb on it, knife slid under the fork"]'::jsonb, 'Turn the fork handle towards your thumb and hold it down with your thumb, then slide the knife underneath the fork so nothing slides around.', 'Cutlery that can''t move won''t fall on a guest or the floor.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 8', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0020', 'service', 'service-steps', 1, array['server','host','runner','bar','barista']::text[], 'scenario', 'Guests stand up to leave while you''re in the middle of a task. What do you do?', '["Nod and smile, then carry on", "Pause to thank them and say goodbye", "Finish your task, then wave as they go", "Leave the farewell to the host at the door"]'::jsonb, '["Pause to thank them and say goodbye"]'::jsonb, 'Even mid-task, pause briefly to thank the guests, get their feedback and say goodbye.', 'The last moment is often the one guests remember.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 11', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)'),
  ('svc-service-steps-0021', 'service', 'service-steps', 1, array['server','runner']::text[], 'mcq', 'Guests have just left. Where do you check for anything they''ve forgotten?', '["Under the table only", "On the table and the chairs, and by the entrance", "On the table, on the chairs and under the table", "On the table only"]'::jsonb, '["On the table, on the chairs and under the table"]'::jsonb, 'Check on top of the table, on the chairs and below the table so guests don''t forget anything.', 'Catching a phone or bag before the guest reaches their car saves a stressful trip back.', false, 'Sequence of service steps, 11-step document (from David, 20 Oct 2026), step 11', 'Drafted by Claude 2026-10-20 from Sequence of service steps, 11-step document (from David, 20 Oct 2026).', 'review', 'Claude (draft for David)')
on conflict (id) do nothing;

